evidence.en:
// naive — exponential:
function fib(n) {
  if (n <= 1) return n;
  return fib(n - 1) + fib(n - 2);
}

// memoized:
const memo = new Map();
function fibMemo(n) {
  if (n <= 1) return n;
  if (memo.has(n)) return memo.get(n);
  const result = fibMemo(n - 1) + fibMemo(n - 2);
  memo.set(n, result);
  return result;
}

// teammate's claim:
// 'fibMemo is basically as fast as binary search'
// 'both avoid redundant work'
// 'both should be log n'

